CREATE TABLE things (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  flag TINYINT(1),
  count INT UNSIGNED NOT NULL,
  price DECIMAL(10,2) NOT NULL,
  uprice DECIMAL(10,2) UNSIGNED,
  plain DECIMAL,
  ratio FLOAT(7,4),
  f FLOAT,
  title VARCHAR(255),
  code CHAR(3),
  kind ENUM('a','b'),
  flags SET('x','y'),
  doc JSON,
  key16 BINARY(16),
  blob255 VARBINARY(255),
  created DATETIME(6),
  updated TIMESTAMP(3),
  y YEAR,
  bits BIT(8),
  body TEXT,
  bin VARCHAR(10) CHARACTER SET binary,
  geo GEOMETRY,
  ok BOOLEAN,
  d DOUBLE,
  small MEDIUMINT UNSIGNED,
  i INT
);
